<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePhasePage} from '../phasePage'
import {useDocumentExpiryText,type ExpiryItem,type ExpiryPage} from '../documentExpiry'
import PhaseStatus from '../components/PhaseStatus.vue'
import DocumentMaintenanceDialog from '../components/DocumentMaintenanceDialog.vue'
const {api,home,store,t,p,load,loading,failure}=usePhasePage(),{x}=useDocumentExpiryText(),route=useRoute(),router=useRouter()
const days=ref([7,30,60,90,365].includes(Number(route.query.days))?Number(route.query.days):30),status=ref(['all','due','expired'].includes(String(route.query.status))?String(route.query.status):'all'),offset=ref(0),selected=ref<ExpiryItem|null>(null),data=ref<ExpiryPage|null>(null)
function refresh(reset=true){if(!home.value?.employeeManage)return;if(reset)offset.value=0;data.value=null;const query=new URLSearchParams({days:String(days.value),status:status.value,limit:'50',offset:String(offset.value)});void load(()=>api().get<ExpiryPage>('/document-expiries?'+query),result=>{if(offset.value>0&&offset.value>=result.total){offset.value=Math.max(0,Math.floor((result.total-1)/50)*50);refresh(false);return}data.value=result})}
function filter(value:string){status.value=value;refresh()}
function page(delta:number){offset.value=Math.max(0,offset.value+delta);refresh(false)}
function changeStore(event:Event){const id=(event.target as HTMLSelectElement).value;if(!home.value?.stores.some(s=>s.id===id))return;void router.push(`/stores/${encodeURIComponent(id)}/workforce/document-expiries?days=${days.value}&status=${status.value}`)}
onMounted(()=>refresh())
</script>
<template><section v-if="home?.employeeManage" class="wf-panel"><header class="wf-toolbar"><h2>{{x('title')}}</h2><button type="button" :disabled="loading||!!selected" @click="refresh(false)">{{p('reload')}}</button></header><form class="wf-filters" @submit.prevent="refresh()"><label>{{x('store')}}<select :value="store" :disabled="loading||!!selected" @change="changeStore"><option v-for="s in home.stores" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>{{x('days')}}<select v-model="days" :disabled="loading||!!selected"><option v-for="value in [7,30,60,90,365]" :key="value" :value="value">{{value}}</option></select></label><button type="submit" :disabled="loading||!!selected">{{x('query')}}</button></form><p class="wf-hint">{{x('scope')}}</p><PhaseStatus :loading="loading" :failure="failure"/>
 <template v-if="data&&!failure"><p class="wf-hint">{{data.today}} · {{data.timezone}} · {{x('window')}} {{data.days}} {{x('dayUnit')}}</p><div class="wf-inline"><button type="button" :class="status==='all'?'primary':''" :disabled="loading||!!selected" @click="filter('all')">{{x('all')}} {{data.due+data.expired}}</button><button type="button" :class="status==='due'?'primary':''" :disabled="loading||!!selected" @click="filter('due')">{{x('due')}} {{data.due}}</button><button type="button" :class="status==='expired'?'primary':''" :disabled="loading||!!selected" @click="filter('expired')">{{x('expired')}} {{data.expired}}</button></div><div class="wf-table-wrap"><table><thead><tr><th>{{x('employee')}}</th><th>{{x('type')}}</th><th>{{x('expiry')}}</th><th>{{t('status')}}</th><th>{{t('manage')}}</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.documentId"><td><strong>{{row.employeeName}}</strong><small> {{row.employeeNo}}</small></td><td>{{row.typeName}}</td><td>{{row.expiresOn}}</td><td><span class="wf-badge">{{row.status==='expired'?x('expired'):row.daysRemaining===0?x('today'):x('due')}}</span><small> · {{row.status==='expired'?x('overdue'):x('remaining')}} {{Math.abs(row.daysRemaining)}}</small></td><td><button type="button" :aria-label="x('maintain')+' · '+row.employeeName+' · '+row.typeName" @click="selected=row">{{x('maintain')}}</button></td></tr><tr v-if="!data.items.length"><td colspan="5" class="wf-empty">{{x('empty')}}</td></tr></tbody></table></div><footer class="wf-pagination"><span>{{data.total?offset+1:0}}–{{Math.min(offset+50,data.total)}} / {{data.total}}</span><button type="button" :disabled="loading||!!selected||offset===0" @click="page(-50)">{{t('previous')}}</button><button type="button" :disabled="loading||!!selected||offset+50>=data.total" @click="page(50)">{{t('next')}}</button></footer></template>
 </section><p v-else role="alert">{{p('noAccess')}}</p><DocumentMaintenanceDialog v-if="selected" :employee-id="selected.employeeId" :document-id="selected.documentId" :employee-name="selected.employeeName" @close="selected=null" @changed="refresh(false)"/></template>
